tool_input.command:
node << 'EOF'
import('./src/eval/index.js').then(({ generateReport, runEvaluations }) => {
  const evaluations = runEvaluations({
    outputs: ['Hello', 'World'],
    references: ['hello', 'world']
  });

  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: {
      exact_match: 0.5,
      toxicity: 0.9
    }
  });

  console.log('Report passed:', report.passed);
  console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));
});
EOF
